import {pricing,unitEconomics,displayEconomics,money,percent,economicsCSV} from './economics.js';
import {styles} from './plan.js';
import {download} from './assets.js';
const $=id=>document.getElementById(id);
const fields={skuCost:'firstCost',skuPrice:'msrp',additionalCost:'additional',freightCost:'freight',dutyCost:'duty',otherCost:'other'};
const output=(id,label)=>`<div><span>${label}</span><strong id="${id}">—</strong></div>`;
const basis=id=>`<label>Gross profit / weighted IMU basis<select id="${id}"><option value="first">First Cost</option><option value="landed">Estimated Landed Cost</option></select></label>`;
export function installEconomics(){
 $('skuCost').min='0';const first=$('skuCost').closest('label'),retail=$('skuPrice').closest('label');first.firstChild.textContent='First Cost (USD)';retail.firstChild.textContent='MSRP (USD)';
 const detail=document.createElement('details');detail.id='productEconomics';detail.innerHTML=`<summary>Product Economics · USD</summary><p class="hint">Private planning data. Blank means unknown; enter 0 explicitly for no cost. Legacy unit cost / price map to First Cost / assumed MSRP.</p><div class="fields" id="basePrices"></div><label>Additional unit costs<select id="additionalMode"><option value="direct">Enter a combined additional amount</option><option value="separate">Enter Freight, Duty and Other separately</option></select></label><div id="directCosts"><label>Additional Unit Cost (USD)<input id="additionalCost" type="number" min="0" step=".01" placeholder="Unknown"></label></div><div id="separateCosts" class="fields" hidden>${[['freightCost','Freight'],['dutyCost','Duty'],['otherCost','Other Unit Cost']].map(([id,n])=>`<label>${n} (USD)<input id="${id}" type="number" min="0" step=".01" placeholder="Unknown"></label>`).join('')}</div>${basis('economicBasis')}<div class="economicsGrid">${output('landedResult','Estimated Landed Cost')}${output('firstIMU','First Cost IMU')}${output('landedIMU','Landed Cost IMU')}${output('unitProfit','Gross Profit / Unit')}</div><p id="pricingStatus" role="status"></p><p class="hint">Illustrative margins using MSRP as the assumed selling price. Not Walmart’s verified acquisition cost, selling price or actual IMU. No freight or duty is assumed.</p>`;
 $('skuEditor').append(detail);$('basePrices').append(first,retail);
 $('skuSummary').insertAdjacentHTML('afterend',`<details id="displayEconomics" class="economicsPanel"><summary>Display Economics · private planning</summary>${basis('displayEconomicBasis')}<p id="displayEconomicStatus" role="status"></p><div class="economicsGrid">${output('economicUnits','Units in Display')}${output('economicRetail','Retail Value · USD')}${output('economicFirst','First Cost · USD')}${output('economicLanded','Landed Cost · USD')}${output('economicProfit','Estimated Gross Profit · USD')}${output('economicIMU','Weighted Display IMU')}</div><p id="economicMissing" class="hint"></p><button id="economicsCSV">↓ Export confidential economics CSV</button><p class="hint">Exports costs and profitability only when you click this button. Project backups also contain private pricing. Buyer sheets and 3D images exclude supplier costs and profit figures.</p></details>`);
}
export function syncEconomics(sku,project){if(!sku)return;const p=pricing(sku);for(const [id,key] of Object.entries(fields))$(id).value=p[key]??'';$('additionalMode').value=p.mode;for(const id of ['economicBasis','displayEconomicBasis'])$(id).value=project.economicsBasis??'first';updateUnit(sku,project);}
function updateUnit(sku,project){if(!sku)return;const u=unitEconomics(sku,project.economicsBasis??'first'),p=pricing(sku);$('directCosts').hidden=p.mode!=='direct';$('separateCosts').hidden=p.mode!=='separate';$('landedResult').textContent=money(u.landed);$('firstIMU').textContent=percent(u.firstIMU);$('landedIMU').textContent=percent(u.landedIMU);$('unitProfit').textContent=money(u.profit);$('pricingStatus').textContent=u.complete?`Complete · ${u.basis==='first'?'First Cost':'Estimated Landed Cost'} basis`:'Incomplete · '+u.issues.join('. ');$('pricingStatus').className=u.complete?'economicsComplete':'economicsIncomplete';}
export function renderEconomics(project,result,sku){updateUnit(sku,project);for(const id of ['economicBasis','displayEconomicBasis'])$(id).value=project.economicsBasis??'first';const r=displayEconomics(result??{valid:false,counts:{},total:0},project.catalog,project.economicsBasis??'first');$('economicUnits').textContent=r.layoutValid?r.units:'—';for(const [id,m] of [['economicRetail',r.retail],['economicFirst',r.first],['economicLanded',r.landed]])$(id).textContent=r.layoutValid?`${money(m.value)}${m.complete?'':' · known only'}`:'—';$('economicProfit').textContent=money(r.profit);$('economicIMU').textContent=percent(r.imu);$('displayEconomicStatus').textContent=!r.layoutValid?'Layout incomplete · resolve merchandising errors before relying on financial totals.':r.complete?`Complete for ${r.basis==='first'?'First Cost':'Estimated Landed Cost'} basis${r.units?'':' · no merchandise placed'}`:r.numericRange?'Numeric range exceeded · weighted margin unavailable.':'Incomplete · known subtotals only; profit and weighted IMU withheld.';$('displayEconomicStatus').className=r.complete?'economicsComplete':'economicsIncomplete';$('economicMissing').textContent=[['MSRP',r.retail],['First Cost',r.first],['Landed Cost',r.landed]].map(([n,m])=>m.overflow?`${n}: numeric range exceeded`:m.missingUnits?`${n}: ${m.missingUnits} units missing data (${m.missingSKUs.join(', ')})`:`${n}: complete`).join(' · ');$('economicsCSV').disabled=!r.layoutValid;}
export function bindEconomics(getProject,getSku,getResult,onEdit,toast){
 for(const [id,key] of Object.entries(fields)){$(id).oninput=()=>{const sku=getSku();if(!sku)return;sku.economics={...pricing(sku),[key]:$(id).value===''?null:Number($(id).value)};renderEconomics(getProject(),getResult(),sku);onEdit();};$(id).onchange=$(id).oninput;}
 $('additionalMode').onchange=()=>{const sku=getSku();if(!sku)return;sku.economics={...pricing(sku),mode:$('additionalMode').value};renderEconomics(getProject(),getResult(),sku);onEdit();};
 for(const id of ['economicBasis','displayEconomicBasis'])$(id).onchange=()=>{getProject().economicsBasis=$(id).value;renderEconomics(getProject(),getResult(),getSku());onEdit();};
 $('economicsCSV').onclick=()=>{if(!getResult()?.valid)return toast('Resolve merchandising errors first.');download(new Blob([economicsCSV(getProject(),getResult(),styles[getProject().type])],{type:'text/csv;charset=utf-8'}),'display-economics-confidential.csv');toast('Private economics CSV saved locally. It contains supplier costs and profit estimates.');};
}
